func TestTitles(t *testing.T) {
	type in struct {
		lang string
		cont VulnInfo
	}
	var tests = []struct {
		in  in
		out []CveContentStr
	}{
		// lang: ja
		{
			in: in{
				lang: "ja",
				cont: VulnInfo{
					CveContents: CveContents{
						Jvn: []CveContent{{
							Type:  Jvn,
							Title: "Title1",
						}},
						RedHat: []CveContent{{
							Type:    RedHat,
							Summary: "Summary RedHat",
						}},
						Nvd: []CveContent{{
							Type:    Nvd,
							Summary: "Summary NVD",
							// Severity is NOT included in NVD
						}},
					},
				},
			},
			out: []CveContentStr{
				{
					Type:  Jvn,
					Value: "Title1",
				},
				{
					Type:  Nvd,
					Value: "Summary NVD",
				},
				{
					Type:  RedHat,
					Value: "Summary RedHat",
				},
			},
		},
		// lang: en
		{
			in: in{
				lang: "en",
				cont: VulnInfo{
					CveContents: CveContents{
						Jvn: []CveContent{{
							Type:  Jvn,
							Title: "Title1",
						}},
						RedHat: []CveContent{{
							Type:    RedHat,
							Summary: "Summary RedHat",
						}},
						Nvd: []CveContent{{
							Type:    Nvd,
							Summary: "Summary NVD",
							// Severity is NOT included in NVD
						}},
					},
				},
			},
			out: []CveContentStr{
				{
					Type:  Nvd,
					Value: "Summary NVD",
				},
				{
					Type:  RedHat,
					Value: "Summary RedHat",
				},
			},
		},
		// lang: empty
		{
			in: in{
				lang: "en",
				cont: VulnInfo{},
			},
			out: []CveContentStr{
				{
					Type:  Unknown,
					Value: "-",
				},
			},
		},
	}
	for i, tt := range tests {
		actual := tt.in.cont.Titles(tt.in.lang, "redhat")
		if !reflect.DeepEqual(tt.out, actual) {
			t.Errorf("[%d]\nexpected: %v\n  actual: %v\n", i, tt.out, actual)
		}
	}
}

